namespace FramePilot {
 public sealed partial class MainForm {
  ListView driverGrid,installedGrid;TextBox driverDetail,storageDetail;List<DriverEntry> driverRows=new List<DriverEntry>();List<InstalledEntry> installedRows=new List<InstalledEntry>();
  ListView Grid(string[] headings,int[] widths,int height){var v=new ListView{View=View.Details,FullRowSelect=true,MultiSelect=false,HideSelection=false,Width=850,Height=height,BackColor=panel,ForeColor=ink,BorderStyle=BorderStyle.None};for(int i=0;i<headings.Length;i++)v.Columns.Add(headings[i],widths[i]);return v;}
  void InitV3(){try{Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);}catch{}BuildDrivers();BuildStorage();BuildUpdates();AddImpacts();AddImpactTable();Shown+=delegate{string marker=Path.Combine(data,"last-release.txt");if(!File.Exists(marker)||File.ReadAllText(marker)!="3.1.0"){Journal.Atomic(marker,Encoding.UTF8.GetBytes("3.1.0"));}};}
  void AddImpactTable(){var table=Box(140);table.Text="CONDITIONAL POTENTIAL                    FPS       LATENCY\r\nResolution / shadows / effects / Nanite   High      Medium\r\nRender & simulation distance             High      Medium\r\nTextures / view distance                 Medium    Low\r\nV-Sync / FPS cap / frame generation       High      High\r\nAll numerical FPS % and latency ms: unknown until measured.\r\nA gain in displayed frames can coexist with worse input latency.";var p=(FlowLayoutPanel)pages["Game profiles"];p.Controls.Add(table);p.Controls.SetChildIndex(table,3);foreach(string page in new[]{"Background apps","Startup apps","Session mode","Maintenance","Windows tuning"}){var text=Note(page=="Maintenance"?"FPS: Low | Latency: Low | Gain/loss: unmeasured. Quarantine itself frees no disk space.":"Each control: FPS Medium / Latency Low potential under contention. Gain/loss: unmeasured.\r\nPower plans can regress performance. Config-edit lock changes no game performance.",52);var host=(FlowLayoutPanel)pages[page];host.Controls.Add(text);host.Controls.SetChildIndex(text,3);}}
  void BuildDrivers(){var p=Page("Drivers","Drivers, with a recovery route.","Inventory covers Windows PnP driver records. Update availability is checked by the official tools.\r\nFPS: Medium potential / Latency: Medium potential / Numerical change: unmeasured; can regress.");var r=Row();r.Controls.Add(Button("Scan installed drivers",async delegate{await ScanDrivers();}));r.Controls.Add(Button("NVIDIA App",OpenNvidia));r.Controls.Add(Button("Windows Update",delegate{Open("ms-settings:windowsupdate");}));r.Controls.Add(Button("Optional drivers",delegate{Open("ms-settings:windowsupdate-optionalupdates");}));p.Controls.Add(r);driverGrid=Grid(new[]{"Device","Provider","Version","Date","INF","Signed"},new[]{270,145,125,90,110,65},260);p.Controls.Add(driverGrid);driverDetail=Box(80);driverDetail.Text="Scan to list installed versions. Old dates are not proof of an outdated driver.\r\nUpdate Windows drivers in Windows Update, GPU drivers in NVIDIA App, and chipset/OEM packages\r\nfrom their manufacturer. There is no universal safe Update All installer.";p.Controls.Add(driverDetail);var actions=Row();actions.Controls.Add(Button("Export inventory",delegate{if(driverRows.Count==0)throw new Exception("Scan drivers first.");SaveText(Inventory.DriverReport(driverRows),"drivers.tsv");}));actions.Controls.Add(Button("Back up driver packages",async delegate{await BackupDrivers();}));actions.Controls.Add(Button("Rollback / Device Manager",delegate{Open(Path.Combine(Environment.SystemDirectory,"devmgmt.msc"));}));p.Controls.Add(actions);var vendors=Row();vendors.Controls.Add(Button("AMD official support",delegate{Open("https://www.amd.com/en/support");}));vendors.Controls.Add(Button("ASUS official support",delegate{Open("https://www.asus.com/support/download-center/");}));vendors.Controls.Add(Button("NVIDIA older drivers",delegate{Open("https://www.nvidia.com/en-us/drivers/");}));p.Controls.Add(vendors);p.Controls.Add(Note("ROLLBACK: Device Manager > device > Properties > Driver > Roll Back Driver. NVIDIA App may also offer a previous driver under Drivers. If unavailable,\r\nuse a compatible older official installer. Save that installer before upgrading. Package export\r\nis not a complete system backup and excludes Windows inbox drivers. Vendor tools may request\r\nadmin rights or a reboot. Close games first; FramePilot never force-removes drivers.\r\n\r\nUpdates are completed in the official tool. Scan again afterward to record installed versions.",145));}
  async Task ScanDrivers(){if(busy)return;busy=true;Status("Reading installed driver records...");try{driverRows=await Task.Run(()=>Inventory.Drivers());driverGrid.Items.Clear();foreach(var d in driverRows)driverGrid.Items.Add(new ListViewItem(new[]{d.Device,d.Provider,d.Version,d.Date,d.Inf,d.Signed}));driverDetail.Text=driverRows.Count+" installed records. Availability: check official tools. Signature field is Windows inventory data.\r\nScan time: "+DateTime.Now.ToString("g")+". Nothing installed or removed.";Status("Driver inventory refreshed.");}catch(Exception e){Status(e.Message);driverDetail.Text=e.Message;}finally{busy=false;}}
  void OpenNvidia(){string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),@"NVIDIA Corporation\NVIDIA App\CEF\NVIDIA App.exe");Open(File.Exists(path)?path:"https://www.nvidia.com/en-us/software/nvidia-app/");}
  async Task BackupDrivers(){if(busy)return;using(var picker=new FolderBrowserDialog{Description="Select a drive with space for driver packages. A new backup subfolder will be created."}){if(picker.ShowDialog()!=DialogResult.OK)return;string folder=Path.Combine(picker.SelectedPath,"FramePilot-drivers-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));Directory.CreateDirectory(folder);busy=true;try{var records=await Task.Run(()=>Inventory.Drivers());File.WriteAllText(Path.Combine(folder,"inventory.tsv"),Inventory.DriverReport(records));var info=new ProcessStartInfo(Path.Combine(Environment.SystemDirectory,"pnputil.exe"),"/export-driver * "+Releases.Quote(folder)){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden};using(var proc=Process.Start(info)){await Task.Run(()=>proc.WaitForExit());if(proc.ExitCode!=0)throw new Exception("Windows driver export returned "+proc.ExitCode+". The folder may contain a partial export.");}int count=Directory.GetFiles(folder,"*.inf",SearchOption.AllDirectories).Length;driverDetail.Text="Export completed: "+count+" INF packages\r\n"+folder+"\r\nNot a full system backup. Rollback remains managed by Windows or the vendor.";Open(folder);}catch(Exception e){driverDetail.Text=e.Message+"\r\n"+folder;Status("Driver backup not confirmed complete.");}finally{busy=false;}}}
  void BuildStorage(){var p=Page("Storage & apps","Make room for your games.","Read drive capacity and registered desktop apps. Reported app sizes can be missing or inaccurate.\r\nFPS: Low / Latency: Low potential; freeing space has no predictable FPS or latency gain.");storageDetail=Box(115);p.Controls.Add(storageDetail);var r=Row();var filter=new TextBox{Width=275,BackColor=panel,ForeColor=ink,AccessibleName="Search installed apps",Margin=new Padding(0,8,10,0)};r.Controls.Add(filter);r.Controls.Add(Button("Scan drives & apps",async delegate{if(busy)return;busy=true;try{storageDetail.Text=DiskReport();installedRows=await Task.Run(()=>Inventory.Apps());FillApps(filter.Text);Status(installedRows.Count+" registered desktop apps; largest reported sizes first.");}catch(Exception e){storageDetail.Text=e.Message;}finally{busy=false;}}));r.Controls.Add(Button("Windows cleanup",delegate{Open("ms-settings:storagesense");}));p.Controls.Add(r);installedGrid=Grid(new[]{"App","Reported size","Publisher","Version"},new[]{320,125,235,145},300);p.Controls.Add(installedGrid);filter.TextChanged+=delegate{FillApps(filter.Text);};var actions=Row();actions.Controls.Add(Button("Uninstall / manage selected",delegate{if(installedGrid.SelectedItems.Count==0)throw new Exception("Select an app first.");var selected=(InstalledEntry)installedGrid.SelectedItems[0].Tag;Clipboard.SetText(selected.Name);Open("ms-settings:appsfeatures");Status("Copied '"+selected.Name+"'. Paste into Windows' app search, then choose Uninstall.");}));actions.Controls.Add(Button("All apps / Store apps",delegate{Open("ms-settings:appsfeatures");}));actions.Controls.Add(Button("Classic uninstall list",delegate{Open(Path.Combine(Environment.SystemDirectory,"appwiz.cpl"));}));p.Controls.Add(actions);p.Controls.Add(Note("The selected app name is copied for Windows search. Windows/vendor uninstallers handle\r\nremoval and their own prompts; FramePilot does not silently run registry uninstall commands.\r\nApp removal is not reversible through FramePilot. Reinstalling may not recover local saves.\r\nStore apps, shared runtimes and apps without reported size can be reviewed in Windows.\r\nNo game folders, shader caches or user documents are automatically deleted.",125));}
  void FillApps(string search){installedGrid.Items.Clear();foreach(var a in installedRows.Where(x=>(x.Name+" "+x.Publisher).IndexOf(search,StringComparison.OrdinalIgnoreCase)>=0)){var item=new ListViewItem(new[]{a.Name,a.Size==0?"Unknown":(a.Size/1e9).ToString("0.0")+" GB",a.Publisher,a.Version});item.Tag=a;installedGrid.Items.Add(item);}}
  void BuildUpdates(){var p=Page("Updates & notes","FramePilot 3.1.","One portable Windows x64 EXE. Your settings and recovery history stay in your Windows account.\r\nCopy the EXE to share; no account, subscription, service or game hook is installed.");var r=Row();r.Controls.Add(Button("Create desktop EXE",delegate{string target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"FramePilot.exe");if(string.Equals(target,Application.ExecutablePath,StringComparison.OrdinalIgnoreCase)){Status("Already running the desktop EXE.");return;}if(File.Exists(target)){Releases.Validate(target,false);throw new Exception("A desktop copy exists. Run it and use Install local update, or keep it as your older release.");}File.Copy(Application.ExecutablePath,target);Status("Desktop EXE created. It uses the same local preferences.");}));r.Controls.Add(Button("Install local update",InstallRelease));r.Controls.Add(Button("Restore previous app EXE",RestoreRelease));p.Controls.Add(r);var notes=Box(460);notes.Text=Releases.Notes;p.Controls.Add(notes);p.Controls.Add(Note("Local update keeps the previous executable beside this one as .previous. That restores app\r\ncode only; use Recovery to undo settings. Close other FramePilot copies before updating.\r\nA public auto-update service and publisher code signing are not configured for this build.",80));}
  void InstallRelease(){using(var d=new OpenFileDialog{Filter="FramePilot release|*.exe"}){if(d.ShowDialog()!=DialogResult.OK)return;Version version=Releases.Validate(d.FileName,true);string hash=Releases.Hash(d.FileName);if(MessageBox.Show(this,"Install local FramePilot "+version+"?\r\n\r\nSHA-256: "+hash+"\r\n\r\nThis release is not authenticated by FramePilot. Only continue if you trust its source. The app will close and restart.","Install selected release",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;BeginSwap(d.FileName);}}
  void RestoreRelease(){string previous=Application.ExecutablePath+".previous";if(!File.Exists(previous))throw new Exception("No previous app release has been retained beside this EXE."); if(MessageBox.Show(this,"Restore the retained previous app EXE and restart? Settings history is preserved.","Restore app release",MessageBoxButtons.OKCancel)==DialogResult.OK)BeginSwap(previous);}
  void BeginSwap(string file){if(busy)throw new Exception("Wait for the current operation.");EndSession(true);RestorePriorities();if(journal.Items.Any(x=>x.SessionId!=null&&x.Status!="Restored"))throw new Exception("Recover active session changes before updating.");string folder=Path.Combine(data,"updates",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string helper=Path.Combine(folder,"FramePilot-helper.exe"),candidate=Path.Combine(folder,"FramePilot.exe");File.Copy(Application.ExecutablePath,helper);File.Copy(file,candidate);Releases.Validate(candidate,false);using(var current=Process.GetCurrentProcess()){string args="--apply-update "+current.Id+" "+Releases.Quote(Application.ExecutablePath)+" "+Releases.Quote(candidate)+" "+Releases.Hash(candidate)+" "+current.StartTime.ToUniversalTime().Ticks;Process.Start(new ProcessStartInfo(helper,args){UseShellExecute=false,CreateNoWindow=true});}Close();}
  void AddImpacts(){foreach(var entry in pages){if(new[]{"Drivers","Storage & apps","Updates & notes"}.Contains(entry.Key))continue;var page=entry.Value as FlowLayoutPanel;if(page==null)continue;var label=Note("IMPACT ESTIMATES: potential only. Select/hover a setting for its label. FPS % / latency ms: unmeasured.",30);page.Controls.Add(label);page.Controls.SetChildIndex(label,2);Annotate(page);}}
  readonly ToolTip impactTips=new ToolTip{AutoPopDelay=20000,InitialDelay=200};
  void Annotate(Control parent){foreach(Control c in parent.Controls){if(c is CheckBox||c is ComboBox||c is NumericUpDown){string text=Impact(c==resolution?"resolution":c==render||c==simulation?"distance":c==cap?"FPS cap":c==vsync?"V-Sync":graphicOptions.Any(x=>x.Value==c)?graphicOptions.First(x=>x.Value==c).Key:c.Text);impactTips.SetToolTip(c,text);c.Enter+=delegate{Status(text);};c.MouseEnter+=delegate{Status(text);};}if(c.HasChildren)Annotate(c);}}
  static string Impact(string name){string n=name.ToLowerInvariant();string fps="Low",latency="Low";if(new[]{"resolution","distance","shadow","nanite","effects","post","foliage","competitive","frame generation"}.Any(n.Contains))fps="High";if(new[]{"record","capture","game mode","power","startup","texture"}.Any(n.Contains))fps="Medium";if(n.Contains("sync")||n.Contains("cap")||n.Contains("frame generation")){fps="High";latency="High";}if(n.Contains("reflex")||n.Contains("refresh"))latency="High";return "FPS: "+fps+" potential | Latency: "+latency+" potential | Gain/loss: unmeasured; depends on bottleneck.";}
 }
